using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
namespace LightHungry {
    public sealed class NovemberLevelSmokeTest : MonoBehaviour {
        readonly List<string> checks=new List<string>();
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void Boot(){if(Environment.GetCommandLineArgs().Contains("-novemberQA"))new GameObject("November level QA").AddComponent<NovemberLevelSmokeTest>().StartCoroutine("Run");}
        void Check(bool value,string name){string s=(value?"PASS ":"FAIL ")+name;checks.Add(s);Debug.Log(s);}
        GameObject Item(string name,Vector3 at,int face,int layer){var g=new GameObject(name);g.layer=layer;g.transform.position=at;g.AddComponent<FaceMembership>().faces=FaceMembership.ForView(face);return g;}
        MirrorSurface Mirror(string name,Vector3 at,int face,bool depth,float angle,Vector3 size){var g=Item(name,at,face,11);g.transform.rotation=Quaternion.Euler(0,CameraViewController.Yaw(face),0);var m=g.AddComponent<MirrorSurface>();m.continuousRotation=true;m.depthRotation=depth;m.rotationAngle=angle;g.AddComponent<BoxCollider>().size=size;m.Apply();return m;}
        LightEmitter Light(string name,Vector3 at,int face,Vector3 dir,float power=1){var e=Item(name,at,face,13).AddComponent<LightEmitter>();e.useSpatialDirection=true;e.spatialDirection=dir;e.beamWidth=.4f;e.strength=power;e.maxLength=100;return e;}
        IEnumerator Run(){
            yield return new WaitForSeconds(.3f);var session=LabSession.Instance;var player=session.player;var travel=player.GetComponent<LightTravel>();player.automationInput=true;player.GetComponent<LightExposure>().automatic=false;session.useExitCompletion=true;session.deathHeight=-1000;session.GetComponent<LightRouteReview>().automatic=false;
            foreach(var old in FindObjectsOfType<LightEmitter>())old.active=false;foreach(var old in FindObjectsOfType<BeastReceiver>())old.isGoal=false;
            var source=Light("A source",new Vector3(300,40,0),1,Vector3.right);var departure=Mirror("A depth sender",new Vector3(304,40,0),1,true,45,new Vector3(.12f,2,.12f));
            var surface=Item("B receiving plane",new Vector3(304,40,6),2,10).AddComponent<CrossFaceSurface>();surface.GetComponent<BoxCollider>().isTrigger=true;surface.GetComponent<BoxCollider>().size=new Vector3(20,12,.02f);
            var fake=Mirror("B ordinary mirror cannot receive depth",new Vector3(303.94f,40,3),2,false,45,new Vector3(1,2,.2f));
            var beast=Item("B hungry beast",new Vector3(310,40,5.75f),2,12).AddComponent<BeastReceiver>();beast.isGoal=false;beast.gameObject.AddComponent<SphereCollider>().radius=.5f;beast.requiredSeconds=.15f;
            yield return new WaitForSeconds(.15f);Check(session.beams.LastPaths.Any(s=>s.Contains(surface.name)),"Unreceived depth light stops on authored destination plane");Check(!session.beams.LastPaths.Any(s=>s.Contains(fake.name))&&beast.Progress==0,"Plane mirror and beast cannot intercept cross-face light");
            Check(FindObjectsOfType<MeshRenderer>().Any(r=>r.name=="Cross-face light spot"&&r.enabled&&r.gameObject.activeSelf),"World-space destination light spot is visible without text UI");
            var spotRenderer=FindObjectsOfType<MeshRenderer>().First(r=>r.name=="Cross-face light spot");spotRenderer.gameObject.hideFlags=HideFlags.HideAndDontSave;using(new FaceVisibility.RenderScope(RoomFaces.Front))Check(spotRenderer.forceRenderingOff,"Destination spot is isolated even as a DontSave editor preview");spotRenderer.gameObject.hideFlags=HideFlags.None;
            var camera=Camera.main;CameraViewController.Active.observationCenter=new Vector3(304,40,6);CameraViewController.Active.EndTravelView(2);yield return null;Directory.CreateDirectory("Verification");var rt=new RenderTexture(800,600,24);var oldRT=RenderTexture.active;camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var tex=new Texture2D(800,600,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,800,600),0,0);tex.Apply();File.WriteAllBytes("Verification/november-spot.png",tex.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=oldRT;rt.Release();Destroy(rt);Destroy(tex);
            CameraViewController.Active.EndTravelView(1);Check(travel.LaunchFromLight(new Vector3(300,40,0),Vector3.right,20),"Launch toward unreceived destination plane");yield return new WaitForSeconds(.58f);Check(!travel.IsTravelling&&travel.LastResult=="Arrived at face surface"&&CameraViewController.Active.CurrentView==2,"Photon materializes on B before a receiving mirror exists");Check(Mathf.Abs(player.transform.position.x-303.94f)<.15f&&Mathf.Abs(player.transform.position.z-5.99f)<.15f,"Surface landing follows ray intersection without paired teleport coordinates");
            var receiving=Mirror("B receiving depth mirror",new Vector3(303.94f,40,5.85f),2,true,45,new Vector3(.2f,2,.2f));yield return new WaitForSeconds(.25f);Check(beast.Satisfied,"Moving a real receiving depth mirror into spot restores usable planar light");
            receiving.gameObject.SetActive(false);var wall=Item("Blocked B landing",new Vector3(303.94f,40,6),2,8).AddComponent<BoxCollider>();wall.size=new Vector3(2,3,1);CameraViewController.Active.EndTravelView(1);travel.LaunchFromLight(new Vector3(300,40,0),Vector3.right,20);yield return new WaitForSeconds(.55f);Check(travel.IsTravelling&&travel.LastResult=="Surface landing blocked","Blocked destination never restores body inside wall");travel.Cancel();Destroy(wall.gameObject);
            surface.gameObject.SetActive(false);source.active=false;fake.gameObject.SetActive(false);departure.gameObject.SetActive(false);CameraViewController.Active.EndTravelView(1);
            var weak=Light("Weak path",new Vector3(400,40,0),1,Vector3.right);var strong=Light("Strong vertical",new Vector3(405,36,0),1,Vector3.up,2);yield return new WaitForSeconds(.1f);travel.LaunchFromLight(new Vector3(400,40,0),Vector3.right,20,new OpticalRoute{view=1},weak);yield return new WaitForSeconds(.4f);Check(travel.Takeovers==1&&travel.Direction.y>.99f&&travel.TravelStrength==2,"Stronger crossing light takes over moving photon");Check(travel.Route.view==1&&!travel.Route.inTransit,"Takeover preserves logical face");travel.Cancel();
            strong.strength=1;yield return new WaitForSeconds(.1f);travel.LaunchFromLight(new Vector3(400,40,0),Vector3.right,20,new OpticalRoute{view=1},weak);yield return new WaitForSeconds(.4f);Check(travel.Takeovers==0&&travel.Direction.x>.99f,"Equal-strength crossing light never steals photon");travel.Cancel();
            strong.strength=3;strong.GetComponent<FaceMembership>().faces=RoomFaces.Back;yield return new WaitForSeconds(.1f);travel.LaunchFromLight(new Vector3(400,40,0),Vector3.right,20,new OpticalRoute{view=1},weak);yield return new WaitForSeconds(.4f);Check(travel.Takeovers==0,"Stronger light on another face cannot take over photon");travel.Cancel();
            strong.GetComponent<FaceMembership>().faces=RoomFaces.Front;var occluder=Item("Strong light blocked",new Vector3(405,38,0),1,8).AddComponent<BoxCollider>();occluder.size=Vector3.one;yield return new WaitForSeconds(.1f);travel.LaunchFromLight(new Vector3(400,40,0),Vector3.right,20,new OpticalRoute{view=1},weak);yield return new WaitForSeconds(.4f);Check(travel.Takeovers==0,"Occluded strong source has no capture path beyond wall");travel.Cancel();Destroy(occluder.gameObject);weak.active=strong.active=false;
            var exposure=player.GetComponent<LightExposure>();exposure.automatic=true;exposure.secondsRequired=100;exposure.Protect();yield return new WaitForSeconds(1);exposure.BeginFrame();exposure.Receive(weak,Vector3.right,Vector3.zero,new OpticalRoute{view=1});exposure.Receive(strong,Vector3.up,Vector3.zero,new OpticalRoute{view=1});exposure.EndFrame(.1f);Check(exposure.Incoming.y>.99f,"Body charging chooses strongest incident source independently of scan order");exposure.automatic=false;
            var floor=Item("Reveal platform",new Vector3(450,40,0),1,8);var collider=floor.AddComponent<BoxCollider>();var reveal=floor.AddComponent<RevealDevice>();yield return null;Check(!collider.enabled,"Reveal platform starts without collision");var circuit=floor.AddComponent<DeviceCircuit>();circuit.output=reveal;circuit.inputs.Add(new CircuitInput{source=beast});yield return null;Check(collider.enabled&&reveal.state,"Fed beast drives revealed platform through existing circuit");int fedEvents=0;beast.onSatisfied.AddListener(()=>fedEvents++);beast.Clear();yield return null;Check(!collider.enabled,"Clearing beast resets driven platform");beast.Lit=true;beast.Tick(1);beast.Tick(1);Check(fedEvents==1,"Beast satisfaction event fires once per feed cycle");yield return null;Check(!session.Completed,"Intermediate fed beast does not complete exit-based level");
            var lens=Item("Refracting platform",new Vector3(504,40,0),1,11).AddComponent<LensSurface>();lens.deflectionDegrees=30;var lensCollider=lens.gameObject.AddComponent<BoxCollider>();lensCollider.size=new Vector3(.1f,4,1);lensCollider.isTrigger=true;var lensSource=Light("Lens path",new Vector3(500,40,0),1,Vector3.right);yield return new WaitForSeconds(.1f);Check(session.beams.PathSegments.Any(s=>s.source==lensSource&&s.Direction.y>.45f),"Configured lens applies deterministic planar deflection to light beam");travel.LaunchFromLight(new Vector3(500,40,0),Vector3.right,20);yield return new WaitForSeconds(.3f);Check(travel.IsTravelling&&travel.Direction.y>.45f,"Photon uses same configured lens deflection");travel.Cancel();lensSource.active=false;
            var chainSource=Light("Long path source",new Vector3(600,40,0),1,Vector3.right);chainSource.segmentLimit=64;chainSource.maxLength=200;var chain=new List<GameObject>();for(int i=1;i<=15;i++){var g=Item("Straight lens "+i,new Vector3(600+i*2,40,0),1,11);g.AddComponent<LensSurface>();var c=g.AddComponent<BoxCollider>();c.size=new Vector3(.1f,2,1);c.isTrigger=true;chain.Add(g);}yield return new WaitForSeconds(.1f);Check(session.beams.PathSegments.Count(s=>s.source==chainSource)>12,"Long beam paths are no longer cut at twelve segments");travel.LaunchFromLight(new Vector3(600,40,0),Vector3.right,40);yield return new WaitForSeconds(.85f);Check(travel.IsTravelling&&travel.Reflections>=15,"Photon survives more than twelve optical interactions");travel.Cancel();chainSource.active=false;
            var body=player.Body3D;CameraViewController.Active.EndTravelView(1);player.SetSpatialPosition(new Vector3(700,39.3f,0));var opposite=Item("Opposite overlapping physical wall",new Vector3(700,40,0),2,8).AddComponent<BoxCollider>();opposite.size=new Vector3(3,3,1);FindObjectOfType<FaceCollisionIsolation>().Refresh();var own=body.GetComponentInChildren<Collider>();Check(Physics.GetIgnoreCollision(own,opposite),"Other-face wall is excluded from rigidbody contact");opposite.GetComponent<FaceMembership>().faces=RoomFaces.Front;FindObjectOfType<FaceCollisionIsolation>().Refresh();Check(!Physics.GetIgnoreCollision(own,opposite),"Same-face contact remains enabled");Destroy(opposite.gameObject);
            var pulley=Item("Latched rope",new Vector3(740,40,0),1,13).AddComponent<PulleyRope>();pulley.load=new GameObject("QA load").transform;pulley.height=.05f;pulley.speed=10;pulley.lockAtTop=true;yield return null;pulley.Hold(player,.1f);yield return new WaitForSeconds(.15f);Check(pulley.Progress>=.049f,"Optional top latch holds pulley after release");pulley.Unlock();yield return new WaitForSeconds(.12f);Check(pulley.Progress<.001f,"Pulley can unlock and fall again");
            var following=CameraViewController.Active;following.followPlayer=true;following.followSpeed=100;yield return new WaitForSeconds(.12f);var viewport=Camera.main.WorldToViewportPoint(player.transform.position+following.followOffset);Check(Mathf.Abs(viewport.x-.5f)<.05f&&Mathf.Abs(viewport.y-.5f)<.05f,"Optional camera follow keeps distant level sections in view");following.followPlayer=false;
            var exit=Item("End level exit",new Vector3(760,40,0),1,13).AddComponent<LevelExit>();exit.GetComponent<BoxCollider>().isTrigger=true;exit.requiredBeasts=new[]{beast};player.SetSpatialPosition(new Vector3(760,40,0));beast.Clear();Check(!exit.TryEnter(player)&&!session.Completed,"Hungry prerequisite blocks exit");beast.Lit=true;beast.Tick(1);exit.GetComponent<FaceMembership>().faces=RoomFaces.Back;Check(!exit.TryEnter(player),"Exit on opposite face cannot complete level");exit.GetComponent<FaceMembership>().faces=RoomFaces.Front;Check(exit.TryEnter(player)&&session.Completed&&session.CompletionNoticeVisible,"Ready exit completes level with existing notice");Check(!exit.TryEnter(player),"Exit completion cannot trigger twice");
            File.WriteAllLines("Verification/november-level-qa.txt",checks);Application.Quit(checks.Any(s=>s.StartsWith("FAIL"))?1:0);
        }
    }
}
